INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d5ebdd44-b4fe-4f06-9e65-05a67fca7cf4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$71. óra: Egyenes arányosság$q$, $q$Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "abf3f720-f9c4-4b50-a84a-65992c8d8ba1", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "42aea7df-deb3-4cc7-8704-16e2d1c028d4", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "afab9c03-efe9-4028-9ecd-49ca5d2f9f4c", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "8b920f19-dbc9-4155-9859-cb39b16c6673", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "daa74700-a532-49bb-b893-5876d583bd65", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "a609ac2c-592b-4301-ba48-b2e08297bb9a", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "a512e88c-bea3-475d-9838-cf1edfb9f7ac", "text": "Igaz", "isCorrect": true}, {"id": "c85c9b67-9e12-4713-9d7b-c46602a7ac4d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ed91f9ed-c73b-47da-8ba1-1af0430222bf", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "44b96441-e488-4296-8c19-e452caba237b", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "19e942f2-be41-4570-94b1-669c7fb9aba3", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "17cb8f5a-7cc4-4af1-8e23-5d57319ce52c", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "c46ccf1b-8400-44dd-9db6-cea31ad602eb", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "3d6bbe32-a90c-403f-bac1-bf3ba8e48a3b", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "602a4cba-8cae-4ed9-a26f-1dfde5ecbf9f", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "33104ee5-a795-4b37-9d82-636035ef61f8", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "ef41f409-0555-4d65-9cc0-5985e6f79cf5", "text": "Igaz", "isCorrect": true}, {"id": "12a14b1e-2dcf-44c0-8f91-3a27eb0d35f2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1174d518-b3fd-4812-8be7-a91b7f1123a2", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b43ebb04-1774-438b-ad78-c817ba558632', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$72. óra: Egyenes arányosság grafikonja$q$, $q$Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "bf029150-42cd-488d-b4e9-5049e3cdfbec", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "a40beb76-36e6-4e27-a53a-7307f2abd067", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "29bfc1e4-3873-44da-a1e0-11db46bd5482", "text": "Parabola", "isCorrect": false}, {"id": "82a64bcb-68a4-4d05-8342-052ad2eac26e", "text": "Körvonal", "isCorrect": false}, {"id": "3eb674df-9e49-41d8-919e-59abf2f9dec2", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "b9f151d2-84a6-4d05-bc52-12f47af478be", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "b147e675-5f67-4a24-9a09-d7cd7c2a52e3", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "b806b945-026b-4031-bec2-9262c2ba1ba9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d385f8b0-83a5-46a6-b2bb-684245911bfc", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "86671ea7-4c78-43d9-9519-99d23ef005d0", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "48b5cdcb-1edc-4ed4-8033-aa8c221e95e1", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "764e449f-ae09-499c-b1cc-9ec486020cef", "text": "Igaz", "isCorrect": true}, {"id": "0b828b1b-269b-4d12-b2aa-4409e6792ab5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b97a1910-8924-43f7-9aff-80dbf1bfc6b4", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "1beb34a1-8bbb-4291-ac6a-afc2adfcdf6c", "text": "Igaz", "isCorrect": true}, {"id": "c9e5cda7-cac5-4951-b470-f1a4685c4454", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "775094bb-9942-4b17-8f21-9d03303b7093", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "5c7d1e92-d896-4d8e-bece-777bce6b1601", "text": "Igaz", "isCorrect": true}, {"id": "514c2c32-b5f8-49b7-ba2a-8959366d4872", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fcc56c6e-c8c1-4313-91a7-ec1f2d447dfd', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$73. óra: Gyakorlóóra$q$, $q$Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "756effeb-fa30-4997-9a62-d535e77e9fc1", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "1769ae32-0f14-4919-bf1b-04d794047770", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "55222294-cb61-4040-ac2d-d2ae366061b8", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "b5c0122f-3664-4a8c-ac56-7c89c53a2e62", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "f56d84c4-bae2-464c-9e8b-a07c30b0052c", "text": "Igaz", "isCorrect": true}, {"id": "a7ca0708-d068-425c-92f6-667600d47632", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c16a01dc-8826-4a8d-b4ef-6f7c82796c87", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "a9aaa09a-e103-4c58-9efd-35dfd3a5f6f1", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "ba062d42-3389-421c-94e6-ff624b923ad1", "text": "Igaz", "isCorrect": true}, {"id": "d6387096-382a-4972-b4c2-37c17d48f50f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4026442c-4bc1-4268-945f-7c1184009e20", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2d174f3a-acd2-49fd-a452-c2518bd9681b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$74. óra: Matematikai játékok$q$, $q$Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "b0006ee8-888b-49d6-b305-60176f1c8466", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "2be93339-498b-42c4-8bb1-68e29ad7f103", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "972db59b-e1b5-4ba5-8768-b2e92e6a2b74", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "7f3b09ca-3d35-4e9d-a9e5-3d2d34dbfcc0", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "9f09db6c-1ae1-48b2-89ed-5c6c88b3e228", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "9504440a-dadc-41d8-858f-a2a4e890ff13", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "fdbfeec1-30f6-432b-986b-d260d5af178b", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "fc3fbd3e-3812-4a10-97c3-dc345bb13775", "text": "Igaz", "isCorrect": true}, {"id": "429d50cd-8436-41a9-8467-af0c9cdc8f02", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cc157015-4c2d-463f-a714-8136bfa748c9", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "2eb3b009-afc6-4a14-91da-afce4c14f3d8", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "9871c4bc-69bf-49b9-95a3-0a30255519c9", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "13f42799-5ccb-47e6-9c95-afa573f71abc", "text": "Igaz", "isCorrect": true}, {"id": "f5898284-54b1-4c7e-ae35-2d76ce4efac5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "705361a5-a4ff-4402-acee-dea4e316c38f", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "905e1acc-cb99-42eb-87c7-0a682208d36a", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "c74032e5-ea32-4959-948e-df7a548b16d3", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "f0dd0a78-d3b2-4b61-bf59-07dd3609e085", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "06f38505-b95d-43e3-ac8d-f843e162351b", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('25468fec-f10a-47a6-9d0e-7005dda81e56', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$75. óra: Szabályok, megfeleltetések$q$, $q$Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "797fde6f-ff17-437e-b9f5-8710e0ecbbb9", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "aac65f09-df95-4e9a-9c8d-28cd9d948905", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "b3c26a28-dd24-44c6-b899-5c223e920e69", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "d43a5fc9-4130-4df5-a697-0609c1cd047a", "text": "Igaz", "isCorrect": true}, {"id": "92ff58ae-775d-4950-95cc-3355bb6e50c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6612eb23-49c8-4abe-86ec-60531af921e0", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "74829ee4-da4f-4f1a-bfb0-526c248b945a", "text": "Melyik sorozat szabálya a 'Hozzáadás 5-tel'?", "type": "multiple-choice", "options": [{"id": "49d85dc6-8550-474b-98a4-f988518ca6ed", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "e7f3798e-3bf0-4d1c-b4da-1b6923ef91dd", "text": "5, 25, 125", "isCorrect": false}, {"id": "cd4b8ac8-633e-48ee-8d95-3960d02d3e2f", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "dc5491fb-2818-4c89-b486-52f019fa5d5a", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "743f7c41-ac6a-4b66-9ee0-ffd266ec8887", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "2d8a744e-11f2-43fd-8c42-a9ced11f162a", "text": "Igaz", "isCorrect": true}, {"id": "db7c688e-70a2-4c26-9303-9431a87b0519", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "54d7491d-9b81-4723-bd93-0fa69e1569da", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('21f77509-baaa-4a7a-92a3-f8c2ada40981', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$76. óra: Gyakorlóóra$q$, $q$Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "8d615a12-26ef-4036-a0a4-734724eb604a", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "abc59c1f-f5a7-4902-ad3e-43304cc86038", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "08ccc332-2013-4db3-90ed-5ac4ca398197", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "92eb6311-a5e5-4e9d-81af-6cc6e6e14d22", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "168baad2-8a76-4912-a247-ca23443e55da", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "dcf17cbd-7470-428c-aa5f-f524efb566b4", "text": "Igaz", "isCorrect": true}, {"id": "50b752af-c392-4144-bed0-ef3f13a7e7d0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8c5b0b4a-0862-428c-a6a4-0d45262aa2ec", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "cbd986b0-788e-4abc-83af-836e62778653", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "7f17842a-1d8f-4b39-80e6-666acead131f", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "1fd8fffa-08ec-43fc-9473-90c7beb484f4", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "4232d191-6235-40fc-98b5-0a2ed62abde4", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "6731b4e6-0df9-41d2-a419-5440dc42ef2e", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "64e27223-e62f-4312-9143-a21b1ce670ef", "text": "Igaz", "isCorrect": true}, {"id": "269373bf-d9b0-4a48-83b4-5267f3db5392", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5adf36e6-1ea8-4785-8ccc-f36baae86cc0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$77. óra: Törtrész$q$, $q$Törtrész kiszámítása és kapcsolata az egyenes arányossággal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "9ab74f96-3509-4457-b64a-f7efac82f058", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "49f1166e-a8d2-4fd9-b5b1-52b0d83e7fa5", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "c11fc3bb-e4ee-4a62-b5d8-b3d03b428562", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "b58824be-4d37-406b-8365-ec9a93f87ffe", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "a4e3d4c5-f98e-4379-894c-0382e526f780", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "e76a6672-dc08-4c01-b7b6-2c3c50eee58f", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "daecdb34-43d1-4195-a4f0-edf9625eb331", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e28753b2-5407-4427-a319-8aa10681a9d0", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "9804e3a9-df6f-4520-a40a-fecf6d444f35", "text": "Igaz", "isCorrect": true}, {"id": "6d602cfb-dfa7-4fb0-8da5-faf233f11ca6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8ad6440d-a914-4932-bbca-7a8db5e6b751", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "8bdb305c-7c34-418c-b691-bbad853cb6a1", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "b6978cd9-7810-41e1-81d6-61694ffabc44", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('028c4fb9-088a-4ddd-94a4-c6c5023477a7', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$78. óra: Feladatmegoldás$q$, $q$Összetett feladatok megoldása törtrész kiszámításával.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "4dd25484-106f-4255-8423-d127d4f9fe86", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "71207307-f5f5-4f68-a86c-be7891b36962", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "a32e3cc0-e57b-48e3-b3cf-cadce2689260", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "0da1eaf3-63bf-447a-97ad-d08f8dfb330e", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "30146e42-9b82-4265-b30a-ad71041cba06", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "b49c9d57-041c-4adc-ad5c-6c182f58fe96", "text": "Igaz", "isCorrect": true}, {"id": "d1ab56c9-f991-4f23-9125-5e0fe5651339", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "608f37e9-9540-4694-bb70-8eac590772b3", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "9a60a016-b150-4568-afd2-95d89b99fa38", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "2fda0fa8-9d77-418d-849c-f76e34119f42", "text": "Igaz", "isCorrect": true}, {"id": "56db941b-99dd-4c27-94d7-f689be8eb8fe", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('816edc1d-36b4-4ae3-84f2-f518dd7be982', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$79. óra: Számonkérés$q$, $q$Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "95c28d57-cbbe-4ded-b3b0-03d648fb103b", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "d27336dc-42c3-46ba-84e5-46b6d8f51c24", "text": "1 : 3", "isCorrect": true}, {"id": "9bb54f44-627e-4b57-a6cb-bdf17b282842", "text": "1 : 2", "isCorrect": false}, {"id": "8f5ee58e-bc8c-4681-a09e-5334dd6121d1", "text": "3 : 1", "isCorrect": false}, {"id": "6bdaf34f-e436-4015-bbe5-b0fc1b108a03", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "41403b4f-69c0-440f-86fc-19f46f46866a", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "bc14d5e1-23e9-4401-a7f5-af551e4ec6d7", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "ab20112d-dce9-431c-999f-366ce52bcf12", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "5717f2c9-027f-4eec-9346-9b9f9d294bed", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "9669f622-3598-4f90-a61c-f7bb3ad713d3", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "ac393356-de9d-4e5a-94c9-acb7f1794674", "text": "Igaz", "isCorrect": true}, {"id": "66be742b-0859-4ac5-8b40-4a1acbbf65b0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3861f508-b7a5-4258-b50d-da043bda5a3a", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "03462096-4791-4a09-8993-f862e8287233", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "86d5f3c5-8be2-4c75-a61a-b76fad09f2a7", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "3191b369-a125-4612-aa93-8a059c7a7d0a", "text": "Igaz", "isCorrect": true}, {"id": "08fcf36b-2395-4aa2-9453-514e5ec7cc07", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04bfb837-089b-4f6d-ac4f-dba8c0c89426", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fb9881b5-1034-4572-98cd-d9de7bedef8d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$80. óra: Létraverseny I.$q$, $q$Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Arány, százalék, szöveges feladatok$q$, $q$[{"id": "8d36ddb2-c6f3-4ff4-ab17-e891e2b532b5", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "0adc12e7-8594-4899-a634-6f191d43ec77", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "d3919369-782c-4bfa-b1b3-cb0929d6eabe", "text": "1 : 3", "isCorrect": true}, {"id": "113891a9-9275-4257-a1c9-c2f634f3b7bd", "text": "1 : 5", "isCorrect": false}, {"id": "5f354c39-2aa4-4e67-a4f5-63ee799e6ae0", "text": "3 : 1", "isCorrect": false}, {"id": "55daebe7-5dee-427c-8d6d-e222f040f095", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "c2d25368-6b2f-4224-932f-e80bb2be2f14", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "11e3c814-430e-4cd0-9487-fb5713983bac", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "f9484fb6-bb7a-4403-ae82-58122f566471", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "7f15cf94-fe72-4009-8ff6-7a89cbd46883", "text": "Igaz", "isCorrect": true}, {"id": "d2a1d6d5-809a-4ab3-b759-734ec295a454", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99eaf6a3-ac07-480f-ac78-3f9dfc1b36bf", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "16e17a88-4bb5-4a3f-a89f-28d9ad5db696", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "997d844c-61fd-4c24-91e6-5c1699a055a8", "text": "Igaz", "isCorrect": true}, {"id": "c5cd2b33-b5b8-444c-ba57-9a5505d71358", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;